import { Inject, Logger, forwardRef } from '@nestjs/common';
import { ServicesService } from '../services/services.service';
import { InvoicesService } from '../invoice/invoices.service';
import { Billing, billingScheduleConsumers } from './entities/billing.entity';
import { randomUUID } from 'crypto';
import { Process, Processor } from '@nestjs/bull';
import { CreateBillingReportDto } from './dto/createBillingReport.dto';
import { Job } from 'bull';
import { SchedulerEntity } from '../scheduler/entities/scheduler.entity';
import { CustomerService } from '../customer/customer.service';
import { OfferingService } from '../offering/offering.service';
import { AuditService } from '../audit/audit.service';
import { AuditScope } from '../audit/entities/audit.interface';
import { validBillingCycles } from '../offering/dto/createOffering.dto';

@Processor('scheduler_billing_queue')
export class BillingService {
    private static readonly logger = new Logger(BillingService.name);
    constructor(
        @Inject(forwardRef(() => ServicesService)) readonly servicesService: ServicesService,
        @Inject(forwardRef(() => InvoicesService)) readonly invoicesService: InvoicesService,
        @Inject(forwardRef(() => CustomerService)) readonly customerService: CustomerService,
        @Inject(forwardRef(() => OfferingService)) readonly offeringService: OfferingService
    ) {}

    @Process({ name: billingScheduleConsumers.billingReport })
    async create({ data: { scheduleParameters } }: Job<SchedulerEntity>) {
        const { customerId, businessID } = scheduleParameters as CreateBillingReportDto;
        BillingService.logger.log(`Processing billing for customer:${customerId} in business: ${businessID}`);

        try {
            // 1. Resolve the customer and its offering
            const customerResponse = await this.customerService.findOne({ customerId, businessID });
            const customer = customerResponse.data[0];

            if (!customer.offeringId) {
                BillingService.logger.log(`Customer ${customerId} has no offering, skipping billing`);
                return;
            }

            // 2. Resolve the offering to get billing cycle
            const offeringResponse = await this.offeringService.findOne({
                businessID,
                offeringId: customer.offeringId,
            });
            const offering = offeringResponse.data[0];

            if (!offering.billingCycle) {
                BillingService.logger.log(`Offering ${offering.offeringId} has no billing cycle, skipping billing`);
                return;
            }

            // 3. Derive the offering billing-cycle time range
            const { startTime, endTime } = Billing.billingCycleToTimeRange(offering.billingCycle as validBillingCycles);

            // 4. Call the existing usage-total invoice path with that exact customer and range
            const invoiceResult = await this.invoicesService.generateInvoiceForUsageTotal({
                businessID,
                customerId,
                start: startTime,
                end: endTime,
                invoicePaymentTerm: undefined,
                invoiceDate: undefined,
            });

            const invoiceId = invoiceResult.invoiceId;
            BillingService.logger.log(`Generated invoice ${invoiceId} for customer ${customerId}`);

            // 5. Persist a billing record containing the returned invoice ID
            const entity = new Billing({
                invoiceId,
                businessID,
                customerId,
                startTime,
                endTime,
                billingId: randomUUID(),
            });

            const point = Billing.transformer(entity, this.invoicesService.influxService);
            await this.invoicesService.influxService.loadPoints(`${process.env.STAGE}-aggregate-usage`, 'paigo', [point]);
            BillingService.logger.log(`Billing record persisted for customer ${customerId}, invoice ${invoiceId}`);
        } catch (error) {
            // 6. Report processing failures through the existing audit channel
            BillingService.logger.error(`Billing failed for customer ${customerId}: ${error?.message}`, error?.stack);
            AuditService.publishEvent({
                message: `Billing processing failed for customer ${customerId} in business ${businessID}`,
                topic: AuditScope.ERROR,
                data: [{ customerId, businessID, error: error?.message, stack: error?.stack }],
            });
            // Re-throw to let Bull handle the job failure (retry/dead letter)
            throw error;
        }
    }
}

