async update(
        { customerId, businessID, subject, ...updatedFields }: UpdateCustomerDto & { subject?: string }
    ): Promise<CreateCustomerResponseDto> {
        CustomerService.logger.log(`Attempting to update saasClientID: ${customerId} for ${businessID}`);
        const {
            data: [{ offeringId: currentOfferingId, ...rest }],
        } = await this.findOne({ customerId, businessID });
        const newOfferingId = updatedFields.offeringId;

        // Handle offeringId change - replace billing schedule
        if (newOfferingId !== currentOfferingId) {
            // Remove old billing schedule if it exists (not an error if missing)
            try {
                await this.schedulerService.remove({ schedulerID: customerId, businessID, isBillingQueue: true });
                CustomerService.logger.log(`Removed old billing schedule for customer ${customerId}`);
            } catch (e) {
                if (e instanceof NotFoundException) {
                    CustomerService.logger.log(`No existing billing schedule for customer ${customerId} to remove`);
                } else {
                    CustomerService.logger.error(
                        `Error removing billing schedule for customer ${customerId}`,
                        e?.stack
                    );
                    AuditService.publishEvent({
                        message: `Error removing billing schedule for customer ${customerId}`,
                        topic: AuditScope.ERROR,
                        data: [e],
                    });
                }
            }

            // Create new billing schedule if new offeringId is provided
            if (newOfferingId) {
                try {
                    await this.schedulerService.create({
                        schedulerID: customerId,
                        schedulerType: schedulerType.billing,
                        schedulerStatus: SchedulerStatus.live,
                        scheduleParameters: { customerId, businessID },
                        rate: SupportedMeasurementFrequencies.monthly,
                        subject,
                        businessID,
                    });
                    CustomerService.logger.log(
                        `Created new billing schedule for customer ${customerId} with offering ${newOfferingId}`
                    );
                } catch (e) {
                    CustomerService.logger.error(
                        `Error creating billing schedule for customer ${customerId}`,
                        e?.stack
                    );
                    AuditService.publishEvent({
                        message: `Error creating billing schedule for customer ${customerId}`,
                        topic: AuditScope.ERROR,
                        data: [e],
                    });
                }
            }
        }

        const { loadPoints } = this.InfluxService;
        const customerEntity = new CustomerEntity({ ...rest, ...updatedFields, customerId, businessID });
        const points = CustomerEntity.transformer(customerEntity, this.InfluxService);
        CustomerService.logger.log('Points', points);
        await loadPoints(`${process.env.STAGE}-config`, `paigo`, points);
        return { message: 'Customer updated added', customerId: customerId };
    }

